/* Light mode */
@media (prefers-color-scheme: light) {
    body {
        background-color: #282424;
        color: #F2FCFF;
        margin: 10px;
        padding: 5px;
    }
}

/* Dark mode */
@media (prefers-color-scheme: dark) {
    body {
        background-color: #282424;
        color: #F2FCFF;
        margin: 10px;
        padding: 5px;
    }
}

th {
    cursor: pointer;
}

.loader {
    border: 16px solid #F3F3F3;
    border-top: 16px solid #3498DB;
    border-radius: 50%;
    width: 120px;
    height: 120px;
    animation: spin 2s linear infinite;

    margin: auto;
    padding: 5px;
}

@keyframes spin {
    0% { transform: rotate(0deg); }
    100% { transform: rotate(360deg); }
}

.scrollable-table {
    margin: auto;
    padding: 2px;
    height: 360px;
    overflow: scroll;
    overflow-x: hidden;
}

table {
    table-layout: fixed;
}

table th, table td {
    overflow: hidden;
}


.github-logo {
    fill: white;
}

